function PCard({ p, n, add, sub }) {
  return (
    <div className="pc">
      <div className="pc-tags">
        {p.bio && <span className="pc-tag bio">Bio</span>}
        {p.local && <span className="pc-tag loc">Local</span>}
        {p.plat && <span className="pc-tag plat">Plat du jour</span>}
      </div>
      <div className="pc-ic" style={{background:"rgba(138,173,59,.15)", borderRadius:8, width:36, height:36, display:"flex", alignItems:"center", justifyContent:"center", color:"var(--apple)"}}>{I.leaf(18,"var(--apple)")}</div>
      <div className="pc-nm">{p.name}</div>
      <div className="pc-bot">
        <div className="pc-px">{p.price.toFixed(2)}€ <span className="pc-un">/{p.unit}</span></div>
        {n === 0 ? (
          <button className="pc-add" onClick={() => add(p.id)}>+</button>
        ) : (
          <div className="qc">
            <button className="qb" onClick={() => sub(p.id)}>−</button>
            <span className="qn">{n}</span>
            <button className="qb" onClick={() => add(p.id)}>+</button>
          </div>
        )}
      </div>
    </div>
  );
}

// ── FIDELITE ────────────────────

function Fid({ stamps }) {
  const next = REWARDS.find(r => r.at > stamps) || REWARDS[REWARDS.length - 1];
  const pct = (stamps / next.at) * 100;

  return (
    <>
      <div className="loy in">
        <div className="loy-top">
          <div>
            <div className="loy-t">Carte Fidélité</div>
            <div className="loy-sub">1 tampon = 5€ d'achat</div>
          </div>
          <div>
            <div className="loy-pts">{stamps}</div>
            <div className="loy-pts-l">tampons</div>
          </div>
        </div>
        <div className="stamps">
          {Array.from({ length: 20 }).map((_, i) => (
            <div key={i} className={`stp ${i < stamps ? "f" : i === next.at - 1 ? "g" : "e"}`}>
              {i < stamps ? "●" : i === next.at - 1 ? "" : ""}
            </div>
          ))}
        </div>
        <div className="loy-bar">
          <div className="loy-bar-info">
            <span>{stamps}/{next.at}</span>
            <span>{next.at - stamps} restant{next.at - stamps > 1 ? "s" : ""}</span>
          </div>
          <div className="loy-bar-bg">
            <div className="loy-bar-fill" style={{ width: `${Math.min(pct, 100)}%` }} />
          </div>
        </div>
        <div className="loy-next">Prochain palier : <b>{next.label}</b></div>
      </div>

      <h3 className="sec-h in d1"><span className="sec-line"/>Récompenses</h3>
      <div className="rwds in d2">
        {REWARDS.map(r => (
          <div className="rwd" key={r.at}>
            <div className={`rwd-c ${stamps >= r.at ? "done" : "wait"}`}>
              {stamps >= r.at ? "" : r.at}
            </div>
            <div className={`rwd-t ${stamps >= r.at ? "done" : ""}`}>{r.label}</div>
          </div>
        ))}
      </div>
    </>
  );
}

// ── PANIER ──────────────────────

function Cart({ cart, add, sub, tot, order, done, setDone, setTab }) {
  const [step, setStep] = useState("cart"); // cart → payment → processing → done
  const [payMethod, setPayMethod] = useState("card");
  const [cardNum, setCardNum] = useState("");
  const [cardExp, setCardExp] = useState("");
  const [cardCvc, setCardCvc] = useState("");
  const [cardName, setCardName] = useState("");

  const items = Object.entries(cart).map(([id, n]) => ({
    p: PRODUCTS.find(x => x.id === +id), n
  })).filter(x => x.p);
  const earned = Math.floor(tot / 5);

  const formatCardNum = (v) => {
    const digits = v.replace(/\D/g, "").slice(0, 16);
    return digits.replace(/(\d{4})(?=\d)/g, "$1 ");
  };

  const formatExp = (v) => {
    const digits = v.replace(/\D/g, "").slice(0, 4);
    if (digits.length > 2) return digits.slice(0, 2) + "/" + digits.slice(2);
    return digits;
  };

  const canPay = payMethod === "card"
    ? cardNum.replace(/\s/g, "").length === 16 && cardExp.length >= 4 && cardCvc.length >= 3 && cardName.length > 1
    : true;

  const handlePay = () => {
    setStep("processing");
    setTimeout(() => {
      order();
      setStep("done");
    }, 2200);
  };

  // Done state
  if (done || step === "done") return (
    <div className="ok-page in">
      <div className="ok-ic" style={{fontSize:28, fontWeight:800, color:"var(--apple-d)"}}>Validé</div>
      <h3>Paiement accepté !</h3>
      <p>Votre commande de <b>{tot > 0 ? tot.toFixed(2) : "—"}€</b> est confirmée. Marion vous prévient par SMS quand c'est prêt.</p>
      {earned > 0 && <p style={{ color: "var(--gold)", fontWeight: 700 }}>+{earned} tampon{earned > 1 ? "s" : ""} fidélité</p>}
      <button className="ok-btn" onClick={() => { setDone(false); setStep("cart"); setTab("home"); }}>Retour à la boutique</button>
    </div>
  );

  // Processing animation
  if (step === "processing") return (
    <div className="pay-processing in">
      <div className="pay-spinner" />
      <h3 className="sec-h" style={{ textAlign: "center", marginBottom: 6 }}>Paiement en cours…</h3>
      <p style={{ color: "var(--text3)", fontSize: 13, textAlign: "center" }}>
        {payMethod === "card" ? "Vérification de votre carte bancaire" : payMethod === "apple" ? "Authentification Apple Pay" : "Authentification Google Pay"}
      </p>
    </div>
  );

  // Empty cart
  if (!items.length) return (
    <div className="cart-0 in">
      <div className="cart-0-ic"></div>
      <h3>Panier vide</h3>
      <p style={{ marginTop: 4 }}>Ajoutez des produits depuis la boutique</p>
    </div>
  );

  // Payment step
  if (step === "payment") return (
    <>
      <button className="pay-back in" onClick={() => setStep("cart")}>← Retour au panier</button>

      <div className="pay-step in">
        <div className="pay-step-dot done"></div>
        <div className="pay-step-line done" />
        <div className="pay-step-dot active">2</div>
        <div className="pay-step-line" />
        <div className="pay-step-dot pending">3</div>
      </div>

      <h3 className="sec-h in">Paiement</h3>

      <div className="pay-total-bar in d1">
        <span className="pay-total-label">Total à payer</span>
        <span className="pay-total-val">{tot.toFixed(2)}€</span>
      </div>

      <div className="pay-methods in d1">
        <button className={`pay-method ${payMethod === "card" ? "sel" : ""}`} onClick={() => setPayMethod("card")}>
          <div className="pay-method-ic card"></div>
          <div className="pay-method-info">
            <div className="pay-method-nm">Carte bancaire</div>
            <div className="pay-method-desc">Visa, Mastercard, CB</div>
          </div>
          <div className="pay-method-check">{payMethod === "card" && ""}</div>
        </button>

        <button className={`pay-method ${payMethod === "apple" ? "sel" : ""}`} onClick={() => setPayMethod("apple")}>
          <div className="pay-method-ic apple"></div>
          <div className="pay-method-info">
            <div className="pay-method-nm">Apple Pay</div>
            <div className="pay-method-desc">Paiement instantané</div>
          </div>
          <div className="pay-method-check">{payMethod === "apple" && ""}</div>
        </button>

        <button className={`pay-method ${payMethod === "google" ? "sel" : ""}`} onClick={() => setPayMethod("google")}>
          <div className="pay-method-ic google">G</div>
          <div className="pay-method-info">
            <div className="pay-method-nm">Google Pay</div>
            <div className="pay-method-desc">Paiement instantané</div>
          </div>
          <div className="pay-method-check">{payMethod === "google" && ""}</div>
        </button>
      </div>

      {payMethod === "card" && (
        <div className="card-form in d2">
          <div className="card-form-title">Paiement sécurisé</div>
          <div className="card-input-group">
            <label className="card-label">Numéro de carte</label>
            <input
              className="card-input"
              placeholder="1234 5678 9012 3456"
              value={cardNum}
              onChange={e => setCardNum(formatCardNum(e.target.value))}
              inputMode="numeric"
            />
          </div>
          <div className="card-input-group">
            <label className="card-label">Nom sur la carte</label>
            <input
              className="card-input"
              placeholder="MARION PARNASO"
              value={cardName}
              onChange={e => setCardName(e.target.value.toUpperCase())}
              style={{ textTransform: "uppercase" }}
            />
          </div>
          <div className="card-row">
            <div className="card-input-group">
              <label className="card-label">Expiration</label>
              <input
                className="card-input"
                placeholder="MM/AA"
                value={cardExp}
                onChange={e => setCardExp(formatExp(e.target.value))}
                inputMode="numeric"
              />
            </div>
            <div className="card-input-group">
              <label className="card-label">CVC</label>
              <input
                className="card-input"
                placeholder="123"
                value={cardCvc}
                onChange={e => setCardCvc(e.target.value.replace(/\D/g, "").slice(0, 4))}
                inputMode="numeric"
                type="password"
              />
            </div>
          </div>
        </div>
      )}

      {payMethod === "card" ? (
        <button className="pay-btn pay-btn-green in d3" onClick={handlePay} disabled={!canPay}>
          Payer {tot.toFixed(2)}€
        </button>
      ) : payMethod === "apple" ? (
        <button className="pay-btn pay-btn-black in d3" onClick={handlePay}>
           Pay — {tot.toFixed(2)}€
        </button>
      ) : (
        <button className="pay-btn pay-btn-green in d3" onClick={handlePay} style={{ background: "#4285F4" }}>
          G Pay — {tot.toFixed(2)}€
        </button>
      )}

      <div className="pay-secure in d3">Paiement chiffré SSL — Stripe</div>

      {earned > 0 && (
        <div className="cart-stmp in d3" style={{ marginTop: 12 }}>+{earned} tampon{earned > 1 ? "s" : ""} fidélité avec cette commande</div>
      )}
    </>
  );

  // Cart step (default)
  return (
    <>
      <div className="pay-step in">
        <div className="pay-step-dot active">1</div>
        <div className="pay-step-line" />
        <div className="pay-step-dot pending">2</div>
        <div className="pay-step-line" />
        <div className="pay-step-dot pending">3</div>
      </div>

      <h3 className="sec-h in">Mon Panier</h3>
      <div className="in d1" style={{ marginBottom: 14 }}>
        {items.map(({ p, n }) => (
          <div className="ci" key={p.id}>
            <span className="ci-ic" style={{background:"rgba(138,173,59,.15)", borderRadius:8, width:32, height:32, display:"flex", alignItems:"center", justifyContent:"center", color:"var(--apple)"}}>{I.leaf(14,"var(--apple)")}</span>
            <div className="ci-nfo">
              <div className="ci-nm">{p.name}</div>
              <div className="ci-px">{p.price.toFixed(2)}€ / {p.unit}</div>
            </div>
            <div className="qc">
              <button className="qb" onClick={() => sub(p.id)}>−</button>
              <span className="qn">{n}</span>
              <button className="qb" onClick={() => add(p.id)}>+</button>
            </div>
            <div className="ci-tot">{(p.price * n).toFixed(2)}€</div>
          </div>
        ))}
      </div>

      <div className="cart-sum in d2">
        <div className="cart-ln"><span>Sous-total ({items.reduce((s, i) => s + i.n, 0)} art.)</span><span>{tot.toFixed(2)}€</span></div>
        <div className="cart-ln"><span>Retrait en boutique</span><span style={{ color: "var(--apple-d)", fontWeight: 700 }}>Gratuit</span></div>
        <div className="cart-tot"><span>Total</span><span>{tot.toFixed(2)}€</span></div>
      </div>

      {earned > 0 && <div className="cart-stmp in d2">+{earned} tampon{earned > 1 ? "s" : ""} fidélité avec cette commande</div>}

      <button className="order-btn in d3" onClick={() => setStep("payment")} disabled={tot === 0}>
        Passer au paiement — {tot.toFixed(2)}€
      </button>
      <p className="order-note in d4">Retrait gratuit à l'épicerie<br />Marion vous prévient par SMS</p>
    </>
  );
}

