// ── MESSAGERIE ──────────────────

function ChatPage({ setTab }) {
  const [messages, setMessages] = useState(INIT_MSGS);
  const [input, setInput] = useState("");

  const send = () => {
    if (!input.trim()) return;
    setMessages(prev => [...prev, { id: Date.now(), from: "me", text: input.trim(), time: new Date().toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" }) }]);
    setInput("");
    setTimeout(() => {
      setMessages(prev => [...prev, {
        id: Date.now() + 1, from: "marion",
        text: "Merci pour votre message ! Je vous réponds dès que possible.",
        time: new Date().toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" })
      }]);
    }, 1500);
  };

  return (
    <>
      <button className="pay-back in" onClick={() => setTab("plus")}>← Retour</button>
      <h3 className="sec-h in">Messagerie</h3>
      <div className="chat-area in d1">
        {messages.map(m => (
          <div key={m.id} className={`chat-msg ${m.from === "me" ? "me" : ""}`}>
            <div className="chat-av">{m.from === "marion" ? "M" : "V"}</div>
            <div>
              <div className="chat-bubble">{m.text}</div>
              <div className="chat-time" style={{ textAlign: m.from === "me" ? "right" : "left" }}>{m.time}</div>
            </div>
          </div>
        ))}
      </div>
      <div className="chat-input-bar in d2">
        <input className="chat-input" placeholder="Écrire un message…" value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === "Enter" && send()} />
        <button className="chat-send" onClick={send}><svg width="18" height="18" viewBox="0 0 24 24" fill="white" stroke="none"><path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/></svg></button>
      </div>
    </>
  );
}

// ── INFO (with back button) ─────

function InfoBack({ setTab }) {
  return (
    <>
      <button className="pay-back in" onClick={() => setTab("plus")}>← Retour</button>
      <Info />
    </>
  );
}

